    def _show_branch_menu(self, event, full_name, original_tag):
        is_local_branch = original_tag.startswith('heads/')
        is_remote_branch = original_tag.startswith('remotes/')
        agent_part = _agent_branch_part(full_name)
        menu = QtWidgets.QMenu()
        copy_full = menu.addAction(N_('Copy "%s"') % full_name)
        copy_part = None
        if agent_part is not None:
            copy_part = menu.addAction(N_('Copy "%s"') % agent_part)
        menu.addSeparator()
        checkout = menu.addAction(N_('Checkout "%s"') % full_name)
        rename = None
        rename_to = None
        rename_to_target = None
        rewind_check = None
        rewind_paths = []
        if is_local_branch:
            rename = menu.addAction(N_('Rename "%s"...') % full_name)
            graph_view = self._graph_view()
            if graph_view is not None:
                basenames = _branch_tip_basenames(
                    graph_view.context, getattr(self.commit, 'oid', None)
                )
                if basenames:
                    rename_to_target = '%s.%s' % (full_name, ','.join(basenames))
                    rename_to = menu.addAction(
                        N_('Rename to "%s"...') % rename_to_target
                    )
            if self._current_branch_name() == full_name:
                rewind_paths = self._modified_paths()
                if rewind_paths:
                    rewind_check = menu.addAction(N_('Rewind check'))
        merge_to = menu.addAction(N_('Merge to...'))
        push_actions = []
        push_force_actions = []
        push_all_action = None
        push_force_all_action = None
        if is_local_branch:
            remotes = self._configured_remotes()
            if remotes:
                menu.addSeparator()
                push_menu = menu.addMenu(N_('Push "%s" to') % full_name)
                push_menu.setIcon(icons.push())
                for remote in remotes:
                    action = push_menu.addAction(remote)
                    push_actions.append((action, remote))
                if len(remotes) > 1:
                    push_menu.addSeparator()
                    push_all_action = push_menu.addAction(N_('All remotes'))
                push_menu.addSeparator()
                for remote in remotes:
                    action = push_menu.addAction(
                        N_('%s (force-with-lease)') % remote
                    )
                    push_force_actions.append((action, remote))
                if len(remotes) > 1:
                    push_force_all_action = push_menu.addAction(
                        N_('All remotes (force-with-lease)')
                    )

        # Remote-tracking labels get a "delete the branch on the remote" entry.
        # Renaming a local branch leaves the ref it was pushed under behind on
        # the remote, and a stale ``agent/{session id}`` ref also blocks pushing
        # ``agent/{session id}.{files}`` ("refname conflict"), so deleting it
        # has to be reachable from the label itself.
        delete_remote = None
        delete_remote_target = (None, None)
        if is_remote_branch:
            delete_remote_target = _split_remote_ref(
                full_name, self._configured_remotes()
            )
            if delete_remote_target[0] is not None:
                menu.addSeparator()
                delete_remote = menu.addAction(N_('Delete "%s"') % full_name)
                delete_remote.setIcon(icons.discard())

        # Optional env-driven entries (``BRANCH_MENU=Stop>_traj/stop.md:...``).
        # Local branches only: committing to remote-tracking refs would
        # require a detached HEAD, which is not what these actions mean.
        custom_actions = []
        if is_local_branch:
            custom_entries = _parse_branch_menu_env()
            if custom_entries:
                menu.addSeparator()
                for label, rel_path in custom_entries:
                    action = menu.addAction(label)
                    custom_actions.append((action, label, rel_path))

        chosen = menu.exec_(event.screenPos())
        if chosen is None:
            return
        for action, label, rel_path in custom_actions:
            if chosen is action:
                graph_view = self._graph_view()
                if graph_view is None or graph_view.context is None:
                    return
                context = graph_view.context
                # The action is contextual to ``full_name``, so the commit
                # must land on that branch. Switch to it first when needed.
                if self._current_branch_name() != full_name:
                    result = cmds.do(cmds.CheckoutBranch, context, full_name)
                    if not result or result[0] != 0:
                        # CheckoutBranch already surfaced the failure (e.g.
                        # dirty worktree); just abort so we don't commit on
                        # the wrong branch.
                        return
                if _edit_file_and_commit(context, label, rel_path):
                    graph_view.merge_finished.emit()
                return
        if chosen is copy_full:
            qtutils.set_clipboard(full_name)
        elif copy_part is not None and chosen is copy_part:
            qtutils.set_clipboard(agent_part)
        elif chosen is checkout:
            graph_view = self._graph_view()
            if graph_view is None:
                return
            result = cmds.do(cmds.CheckoutBranch, graph_view.context, full_name)
            if result and result[0] == 0:
                graph_view.merge_finished.emit()
        elif rename is not None and chosen is rename:
            self._rename_branch(full_name, suggestion=full_name)
        elif rename_to is not None and chosen is rename_to:
            self._rename_branch(full_name, suggestion=rename_to_target)
        elif rewind_check is not None and chosen is rewind_check:
            graph_view = self._graph_view()
            if graph_view is not None:
                from . import rewind as rewind_widget

                # ``run_rewind_check`` performs ``git reset --hard`` and shows
                # modal dialogs that spin a nested event loop. Both end up
                # rebuilding the DAG scene (``scene().clear()``), which would
                # delete *this* ``Label`` item while its ``mousePressEvent`` is
                # still on the C++ event-dispatch stack -> use-after-free crash.
                # Defer the work until after the mouse event has fully returned.
                # The closure must not touch ``self``/this item (it may already
                # be gone); only ``graph_view`` and plain values are captured.
                context = graph_view.context

                def _run_rewind(
                    graph_view=graph_view,
                    context=context,
                    branch=full_name,
                    paths=rewind_paths,
                ):
                    rewind_widget.run_rewind_check(context, branch, paths)
                    graph_view.merge_finished.emit()

                QtCore.QTimer.singleShot(0, _run_rewind)
        elif chosen is merge_to:
            graph_view = self._graph_view()
            if graph_view is not None:
                graph_view.enter_merge_mode(full_name)
        elif delete_remote is not None and chosen is delete_remote:
            graph_view = self._graph_view()
            if graph_view is None:
                return
            remote, branch = delete_remote_target
            # ``DeleteRemoteBranch`` spins nested event loops for its confirm
            # and result dialogs, and its success path refreshes the model,
            # which rebuilds the DAG scene (``scene().clear()``) and deletes
            # *this* ``Label`` while ``mousePressEvent`` is still on the C++
            # event-dispatch stack -> use-after-free. Defer the work until the
            # mouse event has fully returned and keep ``self`` out of the
            # closure; only ``graph_view`` and plain values are captured.
            def _delete_remote_branch(
                graph_view=graph_view,
                context=graph_view.context,
                remote=remote,
                branch=branch,
            ):
                result = cmds.do(cmds.DeleteRemoteBranch, context, remote, branch)
                if result and result[0] and result[1] == 0:
                    graph_view.merge_finished.emit()

            QtCore.QTimer.singleShot(0, _delete_remote_branch)
        elif push_all_action is not None and chosen is push_all_action:
            self._push_branch(full_name, [r for _, r in push_actions], force=False)
        elif push_force_all_action is not None and chosen is push_force_all_action:
            self._push_branch(
                full_name, [r for _, r in push_force_actions], force=True
            )
        else:
            for action, remote in push_actions:
                if chosen is action:
                    self._push_branch(full_name, [remote], force=False)
                    return
            for action, remote in push_force_actions:
                if chosen is action:
                    self._push_branch(full_name, [remote], force=True)
                    return

