                if not log_entry:
                    break
                oid = log_entry[:oid_len]
                try:
                    commit = self._objects[oid]
                except KeyError:
                    try:
                        commit = CommitFactory.new(self.context, log_entry=log_entry)
                    except (KeyError, ValueError):
                        continue
                    self._objects[commit.oid] = commit
                    self._topo_list.append(commit)
                    session_labels = self._session_labels.get(commit.oid)
                    if session_labels:
                        commit.session_labels = session_labels
                yield commit
        else:
            # git init
            status = 0
        self._top_commit = commit
        if status == 0:
            self._build_threads(cmd)
        self._cached = True
        self.returncode = status

